class Spell {
  constructor(name) {
    this.name = name;
  }

  cast() {
    return `Casting ${this.name} with generic power.`;
  }
}

class Fireball extends Spell {
  constructor(name, damage) {
    super(name);
    this.damage = damage;
  }

  cast() {
    return `${this.name} sizzles and deals ${this.damage} fire damage!`;
  }
}

class IceShard extends Spell {
  constructor(name, frostEffect) {
    super(name);
    this.frostEffect = frostEffect;
  }

  cast() {
    return `${this.name} freezes and slows targets with ${this.frostEffect} frost!`;
  }
}

// Example Usage:
const genericSpell = new Spell("Mystic Bolt");
const fireball = new Fireball("Inferno Blast", 50);
const iceShard = new IceShard("Frost Nova", "chilling");

console.log(genericSpell.cast());
console.log(fireball.cast());
console.log(iceShard.cast());

